using System.Text.RegularExpressions;
using PersonalRSS.Application;
using PersonalRSS.Core;
using PersonalRSS.Infrastructure;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddProblemDetails();
builder.Services.AddPersonalRssInfrastructure(builder.Configuration);
var app = builder.Build();
app.UseExceptionHandler();

using (var scope = app.Services.CreateScope())
{
    var repository = scope.ServiceProvider.GetRequiredService<IFeedRepository>();
    var connectionString = builder.Configuration.GetConnectionString("PersonalRss") ?? "Data Source=data/personalrss.db";
    if (connectionString.StartsWith("Data Source=", StringComparison.OrdinalIgnoreCase))
    {
        var directory = Path.GetDirectoryName(Path.GetFullPath(connectionString["Data Source=".Length..]));
        if (directory is not null) Directory.CreateDirectory(directory);
    }
    await repository.InitializeAsync();
}

app.MapGet("/", () => Results.Content(Dashboard.Html, "text/html"));
app.MapGet("/preview/{slug}", () => Results.Content(PreviewPage.Html, "text/html"));
app.MapGet("/health", () => Results.Ok(new { status = "healthy", service = "PersonalRSS" }));
var api = app.MapGroup("/api");
api.MapGet("/feeds", async (IFeedRepository repository, CancellationToken ct) =>
{
    var feeds = await repository.GetFeedsAsync(ct);
    var unreadCounts = await repository.GetUnreadCountsAsync(0.5, ct);
    var totalUnreadCounts = await repository.GetUnreadCountsAsync(0, ct);
    return Results.Ok(feeds.Select(feed => new FeedSummary(feed.Id, feed.Name, feed.Slug, feed.Url, feed.LastRefreshedAt, feed.LastViewedAt, feed.LastError, unreadCounts.GetValueOrDefault(feed.Id), totalUnreadCounts.GetValueOrDefault(feed.Id))));
});
api.MapPost("/feeds", async (CreateFeedRequest request, IFeedRepository repository, CancellationToken ct) =>
{
    if (string.IsNullOrWhiteSpace(request.Name) || !Uri.TryCreate(request.Url, UriKind.Absolute, out var uri) || uri.Scheme is not ("http" or "https"))
        return Results.ValidationProblem(new Dictionary<string, string[]> { ["feed"] = ["Name and an absolute HTTP(S) feed URL are required."] });
    var slug = Slugify(request.Slug ?? request.Name);
    if (string.IsNullOrWhiteSpace(slug)) return Results.ValidationProblem(new Dictionary<string, string[]> { ["slug"] = ["A usable name or slug is required."] });
    if (await repository.GetFeedBySlugAsync(slug, ct) is not null) return Results.Conflict(new { error = $"The slug '{slug}' already exists." });
    var feed = new FeedSource { Name = request.Name.Trim(), Slug = slug, Url = uri.ToString() };
    await repository.AddFeedAsync(feed, ct);
    return Results.Created($"/api/feeds/{feed.Id}", feed);
});
api.MapPut("/feeds/{id:guid}", async (Guid id, RenameFeedRequest request, IFeedRepository repository, CancellationToken ct) =>
{
    var name = request.Name?.Trim();
    if (string.IsNullOrWhiteSpace(name) || name.Length > 200)
        return Results.ValidationProblem(new Dictionary<string, string[]> { ["name"] = ["Enter a feed name of 200 characters or fewer."] });
    var feed = await repository.GetFeedAsync(id, ct);
    if (feed is null) return Results.NotFound();
    feed.Name = name;
    await repository.SaveFeedAsync(feed, ct);
    return Results.Ok(feed);
});
api.MapDelete("/feeds/{id:guid}", async (Guid id, IFeedRepository repository, CancellationToken ct) =>
    await repository.DeleteFeedAsync(id, ct) ? Results.NoContent() : Results.NotFound());
api.MapPost("/feeds/import/opml", async (IFormFile file, FeedImportService service, CancellationToken ct) =>
{
    if (file.Length == 0) return Results.BadRequest(new { error = "Choose a non-empty OPML file." });
    if (file.Length > 5 * 1024 * 1024) return Results.BadRequest(new { error = "OPML files are limited to 5 MB." });
    try
    {
        await using var content = file.OpenReadStream();
        return Results.Ok(await service.ImportAsync(content, ct));
    }
    catch (InvalidDataException exception)
    {
        return Results.BadRequest(new { error = exception.Message });
    }
}).DisableAntiforgery();
api.MapPost("/feeds/{id:guid}/refresh", async (Guid id, FeedRefreshService service, CancellationToken ct) =>
{
    try { return Results.Ok(await service.RefreshAsync(id, ct)); } catch (KeyNotFoundException) { return Results.NotFound(); }
});
api.MapPost("/feeds/{id:guid}/viewed", async (Guid id, IFeedRepository repository, CancellationToken ct) =>
    await repository.MarkFeedViewedAsync(id, DateTimeOffset.UtcNow, ct) ? Results.NoContent() : Results.NotFound());
api.MapPost("/feeds/{id:guid}/unread", async (Guid id, IFeedRepository repository, CancellationToken ct) =>
    await repository.MarkFeedUnreadAsync(id, ct) ? Results.NoContent() : Results.NotFound());
api.MapGet("/articles", async (Guid? feedId, double? minScore, int? limit, IFeedRepository repository, CancellationToken ct) =>
    Results.Ok(await repository.GetArticlesAsync(feedId, Math.Clamp(minScore ?? 0.5, 0, 1), limit ?? 100, ct)));
api.MapPost("/articles/{id:guid}/feedback", async (Guid id, FeedbackRequest request, IFeedRepository repository, CancellationToken ct) =>
{
    if (!Enum.TryParse<FeedbackKind>(request.Kind, true, out var kind) || !Enum.IsDefined(kind))
        return Results.ValidationProblem(new Dictionary<string, string[]> { ["kind"] = ["Use 'VeryInterested', 'Interested', 'NotInterested', or 'NeverThisTopic'."] });
    var article = await repository.GetArticleAsync(id, ct);
    if (article is null) return Results.NotFound();
    var current = (await repository.GetArticlesAsync(article.FeedSourceId, 0, 500, ct)).SingleOrDefault(x => x.Id == id)?.ActiveFeedback;
    if (current == kind)
    {
        await repository.ClearFeedbackAsync(id, ct);
        await repository.SetArticleReadStateAsync(id, false, false, DateTimeOffset.UtcNow, ct);
        return Results.Ok(new { activeFeedback = (FeedbackKind?)null, isUnread = false });
    }
    await repository.SetFeedbackAsync(id, kind, ct);
    await repository.SetArticleReadStateAsync(id, false, false, DateTimeOffset.UtcNow, ct);
    return Results.Ok(new { activeFeedback = kind, isUnread = false });
});
api.MapPut("/articles/{id:guid}/read-state", async (Guid id, ReadStateRequest request, IFeedRepository repository, CancellationToken ct) =>
{
    if (request.Automatic && request.IsUnread) return Results.BadRequest(new { error = "Automatic updates can only mark articles read." });
    var article = await repository.GetArticleAsync(id, ct);
    if (article is null) return Results.NotFound();
    if (request.Automatic && article.IsUnreadPinned) return Results.Ok(new { changed = false, isUnread = true, isUnreadPinned = true });
    await repository.SetArticleReadStateAsync(id, request.IsUnread, request.Automatic, DateTimeOffset.UtcNow, ct);
    return Results.Ok(new { changed = true, isUnread = request.IsUnread, isUnreadPinned = request.IsUnread });
});
api.MapPost("/articles/read", async (MarkArticlesReadRequest request, IFeedRepository repository, CancellationToken ct) =>
{
    var ids = request.ArticleIds?.Distinct().Take(500).ToArray() ?? [];
    if (ids.Length == 0) return Results.ValidationProblem(new Dictionary<string, string[]> { ["articleIds"] = ["Choose at least one article."] });
    var changed = await repository.MarkArticlesReadAsync(ids, request.Automatic, DateTimeOffset.UtcNow, ct);
    return Results.Ok(new { changed });
});
app.MapGet("/feeds/{slug}.xml", async (string slug, double? minScore, HttpRequest request, IFeedRepository repository, IFilteredFeedRenderer renderer, CancellationToken ct) =>
{
    var feed = await repository.GetFeedBySlugAsync(slug, ct);
    if (feed is null) return Results.NotFound();
    var articles = await repository.GetArticlesAsync(feed.Id, Math.Clamp(minScore ?? 0.5, 0, 1), 200, ct);
    var uri = new Uri($"{request.Scheme}://{request.Host}{request.PathBase}{request.Path}{request.QueryString}");
    return Results.Content(renderer.Render(feed, articles, uri), "application/rss+xml; charset=utf-8");
});

app.Run();
static string Slugify(string value) => Regex.Replace(value.Trim().ToLowerInvariant(), "[^a-z0-9]+", "-").Trim('-');
public sealed record CreateFeedRequest(string Name, string Url, string? Slug);
public sealed record RenameFeedRequest(string? Name);
public sealed record FeedbackRequest(string Kind);
public sealed record ReadStateRequest(bool IsUnread, bool Automatic = false);
public sealed record MarkArticlesReadRequest(IReadOnlyList<Guid>? ArticleIds, bool Automatic = false);
public sealed record FeedSummary(Guid Id, string Name, string Slug, string Url, DateTimeOffset? LastRefreshedAt, DateTimeOffset? LastViewedAt, string? LastError, int UnreadCount, int TotalUnreadCount);

internal static class Dashboard
{
    public const string Html = """
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PersonalRSS</title>
<style>
:root{color-scheme:light;--rail:270px;--green:#126a5b;--ink:#17212b;--muted:#607080;--line:#dbe3e7}*{box-sizing:border-box}body{font:15px system-ui;margin:0;color:var(--ink);background:#f3f6f7;overflow:hidden}.app{display:grid;grid-template-columns:var(--rail) minmax(0,1fr);height:100vh}.sidebar{display:flex;min-width:0;flex-direction:column;background:#fff;border-right:1px solid var(--line);box-shadow:5px 0 20px #2636400a;z-index:2}.brand{padding:1.05rem 1rem .8rem;border-bottom:1px solid #edf1f3}.brand h1{font-size:1.25rem;line-height:1.2;margin:0;color:#174d44;letter-spacing:-.02em}.brand p{margin:.22rem 0 0;color:#78868e;font-size:.78rem}.feed-heading{display:flex;align-items:center;gap:.5rem;padding:.85rem .85rem .35rem}.feed-heading h2{font-size:.75rem;margin:0;text-transform:uppercase;letter-spacing:.09em;color:#76848b}.feed-total{margin-left:auto;min-width:1.45rem;padding:.12rem .4rem;border-radius:999px;background:#e5f1ed;color:#0b5b4c;font-size:.74rem;font-weight:750;text-align:center}.refresh-button{padding:.28rem .45rem;border:0;border-radius:6px;background:transparent;color:#52636d;cursor:pointer;font-size:.8rem}.refresh-button:hover{background:#eef4f2;color:#0b5b4c}.refresh-button:disabled{opacity:.5;cursor:wait}#feeds{list-style:none;margin:0;padding:.15rem .45rem .75rem;overflow:auto;flex:1}.source-item{margin:1px 0}.feed-name{display:flex;align-items:center;min-width:0;gap:.5rem;padding:.48rem .55rem;border-radius:7px;color:#41515a;text-decoration:none}.feed-name:hover{background:#f0f5f3;color:#0b5b4c}.source-item.active .feed-name{background:#e4f2ed;color:#084c40;font-weight:720;box-shadow:inset 3px 0 #16866f}.has-unread .feed-name{font-weight:690;color:#263942}.feed-dot{width:.48rem;height:.48rem;border-radius:50%;background:#c4cfd3;flex:0 0 auto}.has-unread .feed-dot{background:#16866f;box-shadow:0 0 0 3px #16866f16}.feed-label{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.unread-count{margin-left:auto;min-width:1.35rem;padding:.1rem .38rem;border-radius:999px;background:#176e60;color:#fff;font-size:.72rem;font-weight:750;text-align:center}.feed-error{color:#a33a2d;margin-left:auto;font-weight:800}.empty-feed{padding:.7rem;color:var(--muted)}.sidebar-footer{border-top:1px solid var(--line);background:#fbfcfc}.message{margin:0;padding:.45rem .8rem;min-height:1.85rem;color:#66767e;font-size:.75rem}.manage{border-top:1px solid #edf1f3}.manage>summary{list-style:none;padding:.75rem .85rem;color:#174d44;font-weight:720;cursor:pointer}.manage>summary::-webkit-details-marker{display:none}.manage>summary::before{content:'⚙';margin-right:.48rem;color:#60766f}.manage[open]>summary{background:#eef5f3}.manage-body{max-height:50vh;overflow:auto;padding:.4rem .55rem .7rem;background:#f7faf9}.manage-body details{margin:.35rem 0;border:1px solid #d9e2e0;border-radius:8px;background:#fff}.manage-body summary{padding:.55rem .65rem;color:#315b53;font-size:.86rem;font-weight:650;cursor:pointer}.manage-body form{display:grid;gap:.45rem;padding:0 .6rem .65rem}.manage-body input,.manage-body select,.manage-body button{min-width:0;width:100%;font:inherit;padding:.52rem .58rem;border:1px solid #bbc7c8;border-radius:7px}.manage-body button{background:var(--green);color:white;border:0;cursor:pointer}.manage-body button:disabled{opacity:.55;cursor:wait}.reader{min-width:0;height:100vh}.reader iframe{display:block;width:100%;height:100%;border:0;background:#f3f6f7}.welcome{display:grid;height:100%;place-items:center;padding:2rem;background:radial-gradient(circle at 50% 35%,#fff 0,#f3f6f7 54%)}.welcome-card{max-width:28rem;text-align:center;color:#52636d}.welcome-mark{display:grid;width:3.2rem;height:3.2rem;margin:0 auto 1rem;place-items:center;border-radius:50%;background:#dfeee9;color:#126a5b;font-size:1.45rem;font-weight:800}.welcome h2{margin:.2rem 0;color:#263942}.welcome p{line-height:1.55}.mobile-bar{display:none}@media(max-width:760px){body{overflow:auto}.app{display:block;height:auto}.sidebar{height:auto;max-height:46vh;position:sticky;top:0;border-right:0;border-bottom:1px solid var(--line)}.brand{display:none}.feed-heading{padding-top:.6rem}#feeds{max-height:30vh}.reader{height:54vh;min-height:440px}.manage-body{max-height:35vh}.mobile-bar{display:block;font-size:.75rem;color:#7a878d;padding:0 .85rem .45rem}}@media(max-width:420px){:root{--rail:100%}.feed-name{padding:.42rem .5rem}.reader{min-height:520px}}
</style><style>[hidden]{display:none!important}</style></head>
<body><div class="app"><aside class="sidebar"><div class="brand"><h1>PersonalRSS</h1><p>Your feeds, quietly filtered.</p></div><div class="feed-heading"><h2>Feeds</h2><span id="feed-total" class="feed-total" title="Unread posts">0</span><button id="refresh" class="refresh-button" type="button" title="Refresh all feeds">↻ Refresh</button></div><p class="mobile-bar">Choose a feed, then read below.</p><ul id="feeds"><li class="empty-feed">Loading feeds…</li></ul><div class="sidebar-footer"><p id="message" class="message" aria-live="polite"></p><details class="manage"><summary>Manage feeds</summary><div class="manage-body"><details><summary>Add a feed</summary><form id="add"><input name="name" placeholder="Feed name" aria-label="Feed name" required><input name="url" type="url" placeholder="Feed address" aria-label="Feed address" required><button>Add feed</button></form></details><details><summary>Import OPML</summary><form id="import"><input name="file" type="file" accept=".opml,.xml,text/x-opml,application/xml,text/xml" required><button>Import feeds</button></form></details><details><summary>Rename a feed</summary><form id="rename"><select name="id" aria-label="Feed to rename" required><option value="">Loading feeds…</option></select><input name="name" aria-label="New feed name" placeholder="New name" maxlength="200" required><button>Rename feed</button></form></details></div></details></div></aside><main class="reader"><div id="welcome" class="welcome"><div class="welcome-card"><div class="welcome-mark">R</div><h2>Choose a feed</h2><p>Select one from the compact list to read its posts here. Unread counts stay visible while you read.</p></div></div><iframe id="reader-frame" name="reader-frame" title="Feed articles" hidden></iframe></main></div>
<script>
const list=document.querySelector('#feeds'),message=document.querySelector('#message'),frame=document.querySelector('#reader-frame'),welcome=document.querySelector('#welcome'),feedTotal=document.querySelector('#feed-total'),refreshButton=document.querySelector('#refresh');
const renameForm=document.querySelector('#rename'),renameSelect=renameForm.querySelector('select'),renameButton=renameForm.querySelector('button');
const removeDetails=document.createElement('details');removeDetails.innerHTML='<summary>Remove a feed</summary><form id="remove-feed"><select name="id" aria-label="Feed to remove" required><option value="">Loading feeds…</option></select><button style="background:#a33a2d">Remove feed</button></form>';document.querySelector('.manage-body').append(removeDetails);
const removeForm=document.querySelector('#remove-feed'),removeSelect=removeForm.querySelector('select'),removeButton=removeForm.querySelector('button');
function syncFeedOptions(select,button,feeds){const selected=select.value;select.replaceChildren();if(!feeds.length){const option=document.createElement('option');option.textContent='No feeds available';option.value='';select.append(option);button.disabled=true;return}for(const feed of feeds){const option=document.createElement('option');option.value=feed.id;option.textContent=feed.name;select.append(option)}if(feeds.some(feed=>feed.id===selected))select.value=selected;button.disabled=false}
function syncManagementOptions(feeds){syncFeedOptions(renameSelect,renameButton,feeds);syncFeedOptions(removeSelect,removeButton,feeds)}
function selectedSlug(){return new URLSearchParams(location.search).get('feed')||localStorage.getItem('personalrss.selectedFeed')||''}
function renderFeeds(feeds){syncManagementOptions(feeds);list.replaceChildren();const total=feeds.reduce((sum,feed)=>sum+(feed.unreadCount??0),0);feedTotal.textContent=total;feedTotal.hidden=total===0;feedTotal.title=`${total} unread ${total===1?'post':'posts'} at the current score`;if(!feeds.length){list.innerHTML='<li class="empty-feed">No feeds yet. Use Manage feeds to add one.</li>';showWelcome();return}const wanted=selectedSlug(),selected=feeds.find(feed=>feed.slug===wanted);for(const f of feeds){const li=document.createElement('li'),count=f.unreadCount??0,a=document.createElement('a');li.dataset.slug=f.slug;li.className=`source-item ${count>0?'has-unread':'is-read'}${selected?.id===f.id?' active':''}`;a.className='feed-name';a.href=`/?feed=${encodeURIComponent(f.slug)}`;a.title=f.lastError?`${f.name} — refresh error: ${f.lastError}`:f.name;a.innerHTML=`<span class="feed-dot" aria-hidden="true"></span><span class="feed-label">${esc(f.name)}</span>${f.lastError?'<span class="feed-error" aria-label="Refresh error">!</span>':count>0?`<span class="unread-count" aria-label="${count} unread">${count}</span>`:''}`;a.onclick=event=>{event.preventDefault();selectFeed(f,true)};li.append(a);list.append(li)}if(selected)selectFeed(selected,false);else showWelcome()}
function selectFeed(feed,pushState){localStorage.setItem('personalrss.selectedFeed',feed.slug);if(pushState)history.pushState({feed:feed.slug},'',`/?feed=${encodeURIComponent(feed.slug)}`);for(const item of list.querySelectorAll('.source-item'))item.classList.toggle('active',item.dataset.slug===feed.slug);welcome.hidden=true;frame.hidden=false;const target=`/preview/${encodeURIComponent(feed.slug)}?embedded=1`;if(!frame.src.endsWith(target))frame.src=target;if(innerWidth<=760)setTimeout(()=>frame.scrollIntoView({behavior:'smooth',block:'start'}),0)}
function showWelcome(){frame.hidden=true;welcome.hidden=false}
async function getFeeds(){const response=await fetch('/api/feeds');if(!response.ok)throw new Error('Could not load feeds.');return response.json()}
async function refreshFeed(feed){try{const response=await fetch(`/api/feeds/${feed.id}/refresh`,{method:'POST'});return{ok:response.ok}}catch{return{ok:false}}}
async function refreshFeeds(feeds){const results=new Array(feeds.length),queue=feeds.map((feed,index)=>({feed,index}));async function worker(){while(queue.length){const item=queue.shift();if(item)results[item.index]=await refreshFeed(item.feed)}}await Promise.all(Array.from({length:Math.min(4,feeds.length)},worker));return results}
async function loadAndRefresh(){refreshButton.disabled=true;let feeds=await getFeeds();renderFeeds(feeds);if(!feeds.length){message.textContent='';refreshButton.disabled=false;return}message.textContent=`Refreshing ${feeds.length} ${feeds.length===1?'feed':'feeds'}…`;const results=await refreshFeeds(feeds);feeds=await getFeeds();renderFeeds(feeds);const total=feeds.reduce((sum,feed)=>sum+(feed.unreadCount??0),0),failed=results.filter(result=>!result.ok).length;message.textContent=`${total} unread${failed?` · ${failed} failed`:''}`;refreshButton.disabled=false}
renameForm.onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target),id=data.get('id'),name=data.get('name');renameButton.disabled=true;const response=await fetch(`/api/feeds/${id}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({name})});message.textContent=response.ok?'Feed renamed.':await errorMessage(response,'Could not rename feed.');if(response.ok){e.target.elements.name.value='';renderFeeds(await getFeeds())}else renameButton.disabled=false};
removeForm.onsubmit=async e=>{e.preventDefault();const feeds=await getFeeds(),feed=feeds.find(item=>item.id===removeSelect.value);if(!feed)return;if(!confirm(`Remove “${feed.name}”?\n\nThis permanently deletes the feed, its stored articles, and their feedback.`))return;removeButton.disabled=true;message.textContent=`Removing ${feed.name}…`;const response=await fetch(`/api/feeds/${feed.id}`,{method:'DELETE'});if(!response.ok){message.textContent=response.status===404?'This feed has already been removed.':'Could not remove this feed.';removeButton.disabled=false;return}if(selectedSlug()===feed.slug){localStorage.removeItem('personalrss.selectedFeed');history.replaceState({},'','/');frame.src='about:blank';showWelcome()}message.textContent='Feed removed.';renderFeeds(await getFeeds())};
document.querySelector('#add').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target);const r=await fetch('/api/feeds',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:d.get('name'),url:d.get('url')})});message.textContent=r.ok?'Feed added.':await errorMessage(r,'Could not add feed.');if(r.ok){e.target.reset();await loadAndRefresh()}};
document.querySelector('#import').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;message.textContent='Importing subscriptions…';const r=await fetch('/api/feeds/import/opml',{method:'POST',body:new FormData(e.target)});if(r.ok){const result=await r.json();message.textContent=`Import complete: ${result.added} added, ${result.skipped} already present, ${result.invalid} invalid.`;e.target.reset();await loadAndRefresh()}else message.textContent=await errorMessage(r,'Could not import that OPML file.');button.disabled=false};
async function errorMessage(r,fallback){try{const body=await r.json();return body.error??Object.values(body.errors??{}).flat()[0]??fallback}catch{return fallback}}function esc(s){const d=document.createElement('div');d.textContent=s??'';return d.innerHTML}
refreshButton.onclick=()=>loadAndRefresh().catch(error=>{message.textContent=error.message;refreshButton.disabled=false});
addEventListener('popstate',async()=>renderFeeds(await getFeeds()));
addEventListener('message',async event=>{if(event.origin!==location.origin)return;if(event.data?.type==='personalrss-feed-changed')renderFeeds(await getFeeds());if(event.data?.type==='personalrss-feed-removed'){localStorage.removeItem('personalrss.selectedFeed');history.replaceState({},'','/');renderFeeds(await getFeeds())}});
loadAndRefresh().catch(error=>{message.textContent=error.message;console.error(error)});
</script></body></html>
""";
}

internal static class PreviewPage
{
    public const string Html = """
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Article preview — PersonalRSS</title>
<style>
:root{color-scheme:light}*{box-sizing:border-box}body{font:16px system-ui;margin:0;color:#17212b;background:#f3f6f7}header{position:sticky;top:0;z-index:2;background:#ffffffee;backdrop-filter:blur(10px);border-bottom:1px solid #dbe3e7}header>div,main{max-width:1050px;margin:auto;padding:1rem 1.25rem}body.embedded header>div,body.embedded main{max-width:1120px}.top{display:flex;align-items:center;gap:.7rem;flex-wrap:wrap}body.embedded .back-link{display:none}h1{font-size:1.5rem;margin:0 auto 0 0}a{color:#126a5b}button,input{font:inherit}button{padding:.55rem .75rem;border:0;border-radius:8px;background:#126a5b;color:white;cursor:pointer}button.secondary{background:#e7eeec;color:#174d44}button.negative{background:#f4e7e5;color:#7a2f26}button.secondary[aria-pressed="true"]{background:#126a5b;color:white;box-shadow:0 0 0 3px #126a5b33}button.negative[aria-pressed="true"]{background:#a33a2d;color:white;box-shadow:0 0 0 3px #a33a2d33}button:disabled{opacity:.55;cursor:wait}.controls{display:flex;align-items:center;gap:.7rem 1rem;flex-wrap:wrap;margin-top:.8rem}.view-toggle{display:flex;gap:.35rem}.view-toggle button{padding:.38rem .65rem}.control-group{display:flex;align-items:center;gap:.5rem}.control-label{color:#52636d;font-size:.9rem;font-weight:700}.auto-read{display:flex;align-items:center;gap:.35rem}.status{min-height:1.5rem;color:#52636d}.cards{display:grid;gap:1rem}.card{display:grid;grid-template-columns:minmax(0,1fr) 230px;gap:1rem;background:white;border:1px solid #dce4e8;border-radius:14px;padding:1.1rem;box-shadow:0 6px 20px #23323d0b}.card.is-unread{border-left:5px solid #16866f;box-shadow:0 7px 24px #126a5b17}.card.is-read{background:#f9fbfb;border-color:#dfe6e9}.card.no-image,.card.is-expanded{grid-template-columns:1fr}.card.is-expanded{grid-column:1/-1}.card.is-expanded>.image{display:none}.card h2{font-size:1.2rem;line-height:1.3;margin:.15rem 0}.meta{display:flex;align-items:center;gap:.45rem;flex-wrap:wrap;color:#64747d;font-size:.88rem}.read-state{display:inline-block;padding:.16rem .5rem;border:0;border-radius:999px;font-size:.75rem;font-weight:750;letter-spacing:.03em;text-transform:uppercase;cursor:pointer}.read-state[aria-pressed="true"]{background:#126a5b;color:white}.read-state[aria-pressed="false"]{background:#e3e9eb;color:#5f6d75;box-shadow:none}.is-read h2 a{color:#50616a}.summary{line-height:1.55;color:#33434c;display:-webkit-box;-webkit-line-clamp:5;-webkit-box-orient:vertical;overflow:hidden}.summary[hidden],.full-content[hidden],.content-toggle[hidden]{display:none}.content-toggle{display:block;background:transparent;color:#126a5b;padding:.2rem 0;margin:.15rem 0 0;border-radius:0;font-weight:700;text-align:left}.card.is-expanded .content-toggle-top{margin:0 0 .65rem}.card.is-expanded .content-toggle-bottom{margin:.65rem 0 0}.reason{font-size:.85rem;color:#64747d}.actions{display:flex;gap:.35rem;flex-wrap:wrap;margin-top:.55rem}.actions button{padding:.38rem .58rem;border-radius:7px;font-size:.9rem}.cards.hide-voting .actions,.cards:not(.show-learning) .score-meta,.cards:not(.show-learning) .reason{display:none}.image{width:100%;height:165px;object-fit:cover;border-radius:10px;background:#e9eeef}.full-content{max-width:760px;line-height:1.65;color:#273841}.full-content img{display:block;max-width:100%;height:auto;margin:1rem auto;border-radius:8px}.full-content table{display:block;max-width:100%;overflow-x:auto;border-collapse:collapse}.full-content th,.full-content td{padding:.35rem .55rem;border:1px solid #d7e0e4}.full-content pre{max-width:100%;overflow-x:auto;padding:.8rem;background:#eef2f3;border-radius:8px}.full-content blockquote{margin-left:0;padding-left:1rem;border-left:3px solid #b8c8ce;color:#53656e}.read-sentinel{grid-column:1/-1;height:1px}.load-older{display:block;margin:1rem auto 0}.load-older[hidden]{display:none}.empty{background:white;padding:2rem;border-radius:14px;text-align:center;color:#607080}.cards.layout-scan .card:not(.is-expanded){grid-template-columns:minmax(250px,38%) minmax(0,1fr);padding:.75rem}.cards.layout-scan .card:not(.is-expanded)>.image{order:-1;height:230px}.cards.layout-scan .card:not(.is-expanded)>.article-body{align-self:center;padding:.45rem}.cards.layout-scan .card:not(.is-expanded) h2{font-size:1.55rem;line-height:1.22;margin:.65rem 0}.cards.layout-scan .card:not(.is-expanded) .meta-details,.cards.layout-scan .card:not(.is-expanded) .summary{display:none}.cards.layout-gallery{grid-template-columns:repeat(auto-fill,minmax(270px,1fr))}.cards.layout-gallery .card:not(.is-expanded){grid-template-columns:1fr;padding:.75rem;align-content:start}.cards.layout-gallery .card:not(.is-expanded)>.image{order:-1;height:210px}.cards.layout-gallery .card:not(.is-expanded) h2{font-size:1.25rem;margin:.65rem .2rem}.cards.layout-gallery .card:not(.is-expanded) .meta{margin:.15rem .2rem}.cards.layout-gallery .card:not(.is-expanded) .meta-details,.cards.layout-gallery .card:not(.is-expanded) .summary{display:none}.cards.layout-gallery .card:not(.is-expanded) .actions{display:grid;grid-template-columns:1fr 1fr;margin:.6rem .2rem 0}.cards.layout-gallery .card:not(.is-expanded) .actions button{font-size:.82rem;padding:.4rem .25rem}.cards.layout-scan .card.no-image:not(.is-expanded),.cards.layout-gallery .card.no-image:not(.is-expanded){min-height:150px;grid-template-columns:1fr}@media(max-width:700px){.card,.cards.layout-scan .card:not(.is-expanded){grid-template-columns:1fr}.image,.cards.layout-scan .card:not(.is-expanded)>.image{order:-1;height:210px}.cards.layout-scan .card:not(.is-expanded) h2{font-size:1.3rem}.control-group{max-width:100%;overflow-x:auto;padding-bottom:.15rem}}
</style></head><body><header><div><div class="top"><a href="/">← Sources</a><h1 id="title">Article preview</h1><button id="remove" class="negative">Remove feed</button></div><div class="controls"><div class="control-group"><span class="control-label">Layout</span><div class="view-toggle" role="group" aria-label="Article layout"><button id="layout-reading" class="secondary" aria-pressed="true">Reading</button><button id="layout-scan" class="secondary" aria-pressed="false">Scan</button><button id="layout-gallery" class="secondary" aria-pressed="false">Gallery</button></div></div><div class="control-group"><span class="control-label">Posts</span><div class="view-toggle" role="group" aria-label="Posts to show"><button id="show-unread" class="secondary" aria-pressed="true">Unread</button><button id="show-all" class="secondary" aria-pressed="false">All</button></div></div><div class="control-group"><span class="control-label">Display</span><div class="view-toggle" role="group" aria-label="Article details"><button id="toggle-voting" class="secondary" aria-pressed="true">Voting</button><button id="toggle-learning" class="secondary" aria-pressed="false">Learning</button></div></div><div class="control-group"><span class="control-label">Feed state</span><div class="view-toggle"><button id="mark-unread" class="secondary">Mark all unread</button><button id="mark-read" class="secondary" disabled>Mark all read</button></div></div><label>Minimum score <strong id="score-label">0.5</strong> <input id="threshold" type="range" min="0" max="1" value="0.5" step="0.1"></label><label class="auto-read"><input id="auto-read" type="checkbox" checked> Mark read while scrolling</label></div><div id="status" class="status" aria-live="polite"></div></div></header><main><div id="cards" class="cards layout-reading"><div class="empty">Loading articles…</div></div><button id="load-older" class="secondary load-older" hidden>Load 25 older read posts</button></main>
<script>
const embedded=new URLSearchParams(location.search).get('embedded')==='1';document.body.classList.toggle('embedded',embedded);if(embedded)document.querySelector('.top>a').hidden=true;document.querySelector('#remove')?.remove();
const slug=decodeURIComponent(location.pathname.substring('/preview/'.length));
const cards=document.querySelector('#cards'),status=document.querySelector('#status'),title=document.querySelector('#title');
const threshold=document.querySelector('#threshold'),scoreLabel=document.querySelector('#score-label'),markRead=document.querySelector('#mark-read'),markUnread=document.querySelector('#mark-unread');
const showUnread=document.querySelector('#show-unread'),showAll=document.querySelector('#show-all'),autoRead=document.querySelector('#auto-read'),loadOlder=document.querySelector('#load-older');
const layoutReading=document.querySelector('#layout-reading'),layoutScan=document.querySelector('#layout-scan'),layoutGallery=document.querySelector('#layout-gallery');
const toggleVoting=document.querySelector('#toggle-voting'),toggleLearning=document.querySelector('#toggle-learning');
let feed,articles=[],temporarilyVisible=new Set(),expandedArticles=new Set(),sessionRead=new Set(),displayOrder=new Map(),renderedArticleIds=[],viewMode='unread',layoutMode='reading',showVoting=true,showLearning=false,readLimit=25;
let readObserver,lastReadObserver,autoFlushTimer;const readTimers=new Map(),autoQueue=new Set();
const dashboardMinimumScore=0.5;
async function start(){autoRead.checked=localStorage.getItem('personalrss.autoRead')!=='false';setLayout(localStorage.getItem('personalrss.articleLayout')||'reading',false);setDisplayOptions(localStorage.getItem('personalrss.showVoting')!=='false',localStorage.getItem('personalrss.showLearning')==='true',false);await refreshFeedState();if(!feed){cards.innerHTML='<div class="empty">Feed not found.</div>';return}title.textContent=feed.name;document.title=`${feed.name} — PersonalRSS`;await load(true)}
async function refreshFeedState(){const feeds=await fetch('/api/feeds').then(r=>r.json());feed=feeds.find(f=>f.slug===slug);updateMarkReadAction()}
async function load(resetOrder=false){articles=await fetch(`/api/articles?feedId=${encodeURIComponent(feed.id)}&minScore=0&limit=500`).then(r=>r.json());prepareDisplayOrder(resetOrder);render()}
function updateMarkReadAction(){const unread=feed?.totalUnreadCount??feed?.unreadCount??0;markRead.textContent=unread>0?`Mark all read (${unread})`:'Mark all read';markRead.disabled=!feed||unread===0}
function isUnread(article){return article.isUnread===true}
function notifyParent(type='personalrss-feed-changed'){if(embedded&&parent!==window)parent.postMessage({type},location.origin)}
function adjustFeedUnread(article,change){if(!feed||!change)return;feed.totalUnreadCount=Math.max(0,(feed.totalUnreadCount??feed.unreadCount??0)+change);if(Number(article.score)>=dashboardMinimumScore)feed.unreadCount=Math.max(0,(feed.unreadCount??0)+change);notifyParent()}
function compareArticles(a,b){const unreadOrder=Number(isUnread(b))-Number(isUnread(a));if(unreadOrder)return unreadOrder;const relevanceOrder=Number(b.score)-Number(a.score);if(relevanceOrder)return relevanceOrder;return new Date(b.publishedAt)-new Date(a.publishedAt)}
function prepareDisplayOrder(reset){if(reset)displayOrder.clear();const ordered=[...articles].sort(compareArticles);let next=displayOrder.size;for(const article of ordered)if(!displayOrder.has(article.id))displayOrder.set(article.id,next++)}
function displaySort(a,b){return (displayOrder.get(a.id)??Number.MAX_SAFE_INTEGER)-(displayOrder.get(b.id)??Number.MAX_SAFE_INTEGER)}
function matchingArticles(){const minimum=Number(threshold.value);return articles.filter(article=>article.score>=minimum||temporarilyVisible.has(article.id)).sort(displaySort)}
function visibleArticles(){const matching=matchingArticles();if(viewMode==='unread')return matching.filter(article=>isUnread(article)||sessionRead.has(article.id));const always=matching.filter(article=>isUnread(article)||sessionRead.has(article.id)),older=matching.filter(article=>!isUnread(article)&&!sessionRead.has(article.id)).slice(0,readLimit),ids=new Set(always.map(article=>article.id));return [...always,...older.filter(article=>!ids.has(article.id))].sort(displaySort)}
function setLayout(mode,persist=true){layoutMode=['reading','scan','gallery'].includes(mode)?mode:'reading';cards.classList.remove('layout-reading','layout-scan','layout-gallery');cards.classList.add(`layout-${layoutMode}`);layoutReading.setAttribute('aria-pressed',String(layoutMode==='reading'));layoutScan.setAttribute('aria-pressed',String(layoutMode==='scan'));layoutGallery.setAttribute('aria-pressed',String(layoutMode==='gallery'));if(persist)localStorage.setItem('personalrss.articleLayout',layoutMode)}
function setDisplayOptions(voting,learning,persist=true){showVoting=voting;showLearning=learning;cards.classList.toggle('hide-voting',!showVoting);cards.classList.toggle('show-learning',showLearning);toggleVoting.setAttribute('aria-pressed',String(showVoting));toggleLearning.setAttribute('aria-pressed',String(showLearning));for(const actions of cards.querySelectorAll('.actions'))actions.hidden=!showVoting;if(persist){localStorage.setItem('personalrss.showVoting',String(showVoting));localStorage.setItem('personalrss.showLearning',String(showLearning))}}
function updateViewActions(){showUnread.setAttribute('aria-pressed',String(viewMode==='unread'));showAll.setAttribute('aria-pressed',String(viewMode==='all'));markUnread.disabled=!feed;const olderCount=matchingArticles().filter(article=>!isUnread(article)&&!sessionRead.has(article.id)).length;loadOlder.hidden=viewMode!=='all'||olderCount<=readLimit;updateMarkReadAction()}
function updateStatus(){const unread=feed?.totalUnreadCount??feed?.unreadCount??0,mode=viewMode==='unread'?'unread view':`all posts; ${readLimit} older at a time`;scoreLabel.textContent=Number(threshold.value).toFixed(1);status.textContent=`Showing ${renderedArticleIds.length} of ${articles.length} loaded posts (${mode}). ${unread} unread across all scores.`}
function render(){disconnectReadObserver();cards.replaceChildren();const visible=visibleArticles();renderedArticleIds=visible.map(article=>article.id);if(!articles.length)cards.innerHTML='<div class="empty">No articles stored yet. Return to Sources to refresh feeds.</div>';else if(!visible.length)cards.innerHTML=`<div class="empty">${viewMode==='unread'?'No unread articles meet this score threshold. Choose All posts to browse read history.':'No articles meet this score threshold.'}</div>`;else for(const article of visible)cards.append(articleCard(article));updateViewActions();updateStatus();setupReadObserver()}
function articleCard(article){const parsed=articleContent(article.summary,article.link),unread=isUnread(article);const card=document.createElement('article');card.className=`card ${unread?'is-unread':'is-read'}${parsed.image?'':' no-image'}`;card.id=`article-${article.id.replaceAll('-','')}`;card.dataset.articleId=article.id;const body=document.createElement('div');body.className='article-body';const meta=document.createElement('div');meta.className='meta';const readState=document.createElement('button');readState.type='button';readState.className='read-state';readState.onclick=()=>setArticleReadState(article,!isUnread(article),card,readState);const metaDetails=document.createElement('span');metaDetails.className='meta-details';metaDetails.textContent=new Date(article.publishedAt).toLocaleString();const scoreMeta=document.createElement('span');scoreMeta.className='score-meta';scoreMeta.textContent=`· relevance ${Number(article.score).toFixed(2)} · baseline ${Number(article.baselineScore).toFixed(2)}`;meta.append(readState,metaDetails,scoreMeta);const heading=document.createElement('h2');const link=document.createElement('a');link.href=article.link;link.target='_blank';link.rel='noopener noreferrer';link.textContent=article.title;heading.append(link);const summary=document.createElement('p');summary.className='summary';summary.textContent=parsed.text||'No summary supplied by this feed.';const reading=document.createElement('div');reading.className='reading';reading.append(summary);let content,toggles;if(parsed.content){content=document.createElement('div');content.className='full-content';content.id=`content-${article.id.replaceAll('-','')}`;content.append(parsed.content);const topToggle=document.createElement('button'),bottomToggle=document.createElement('button');topToggle.type=bottomToggle.type='button';topToggle.className='content-toggle content-toggle-top';bottomToggle.className='content-toggle content-toggle-bottom';toggles=[topToggle,bottomToggle];for(const toggle of toggles){toggle.setAttribute('aria-controls',content.id);toggle.onclick=()=>setArticleExpanded(card,article,summary,content,toggles,!expandedArticles.has(article.id))}reading.append(topToggle,content,bottomToggle)}const reason=document.createElement('p');reason.className='reason';reason.textContent=article.scoreReason||'No scoring explanation available.';const actions=document.createElement('div');actions.className='actions';actions.hidden=!showVoting;actions.append(voteButton(article,'VeryInterested','Very interested','secondary',2),voteButton(article,'Interested','Interested','secondary',1),voteButton(article,'NotInterested','Not interested','negative',-1),voteButton(article,'NeverThisTopic','Never this topic','negative',-2));body.append(meta,heading,reading,reason,actions);card.append(body);if(parsed.image){const image=document.createElement('img');image.className='image';image.src=parsed.image;image.alt='';image.loading='lazy';image.referrerPolicy='no-referrer';card.append(image)}const sentinel=document.createElement('span');sentinel.className='read-sentinel';sentinel.dataset.articleId=article.id;sentinel.setAttribute('aria-hidden','true');card.append(sentinel);updateCardReadAppearance(card,article);if(content&&toggles)setArticleExpanded(card,article,summary,content,toggles,expandedArticles.has(article.id));return card}
function updateCardReadAppearance(card,article){const unread=isUnread(article),button=card.querySelector('.read-state');card.classList.toggle('is-unread',unread);card.classList.toggle('is-read',!unread);button.textContent=unread?'Unread':'Read';button.setAttribute('aria-pressed',String(unread));button.title=unread?'Click to mark this post read.':'Click to mark this post unread and protect it from automatic reading.'}
async function setArticleReadState(article,unread,card,button){button.disabled=true;const response=await fetch(`/api/articles/${article.id}/read-state`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({isUnread:unread,automatic:false})});if(!response.ok){button.disabled=false;status.textContent='Could not update this post’s read state.';return}const wasUnread=isUnread(article);if(unread&&!wasUnread)adjustFeedUnread(article,1);else if(!unread&&wasUnread)adjustFeedUnread(article,-1);article.isUnread=unread;article.isUnreadPinned=unread;article.readAt=unread?null:new Date().toISOString();if(unread)sessionRead.delete(article.id);else sessionRead.add(article.id);updateCardReadAppearance(card,article);button.disabled=false;updateViewActions();updateStatus()}
function setArticleExpanded(card,article,summary,content,toggles,expanded){summary.hidden=expanded;content.hidden=!expanded;const[topToggle,bottomToggle]=toggles;topToggle.hidden=!expanded;topToggle.textContent='Show summary';bottomToggle.textContent=expanded?'Show summary':'Show full feed content';for(const toggle of toggles)toggle.setAttribute('aria-expanded',String(expanded));card.classList.toggle('is-expanded',expanded);if(expanded)expandedArticles.add(article.id);else expandedArticles.delete(article.id)}
function voteButton(article,kind,label,className,kindValue){const button=document.createElement('button'),isActive=article.activeFeedback===kindValue;button.className=className;button.textContent=label;button.setAttribute('aria-pressed',String(isActive));button.title=isActive?'Click again to undo this choice.':kind==='NeverThisTopic'?'Strongly teaches the local model to avoid related articles.':'';button.onclick=async()=>{button.disabled=true;const wasUnread=isUnread(article),response=await fetch(`/api/articles/${article.id}/feedback`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({kind})});if(response.ok){if(kindValue<0&&!isActive)temporarilyVisible.add(article.id);else temporarilyVisible.delete(article.id);if(wasUnread){sessionRead.add(article.id);adjustFeedUnread(article,-1)}await load(false);status.textContent=isActive?`Feedback removed for “${article.title}”; the post remains read.`:`Feedback saved for “${article.title}”. The post is now read and future articles will use this evidence.`}else{status.textContent='Could not update feedback.';button.disabled=false}};return button}
function articleContent(value,base){if(!value?.trim())return{text:'',image:null,content:null};const documentValue=new DOMParser().parseFromString(value,'text/html'),allowedTags=new Set(['A','B','BLOCKQUOTE','BR','CODE','DIV','EM','FIGCAPTION','FIGURE','H1','H2','H3','H4','H5','H6','HR','I','IMG','LI','OL','P','PRE','SPAN','STRONG','SUB','SUP','TABLE','TBODY','TD','TH','THEAD','TR','UL']);documentValue.querySelectorAll('script,style,iframe,object,embed,form,input,button,textarea,select,svg,math').forEach(node=>node.remove());for(const node of [...documentValue.body.querySelectorAll('*')].reverse()){if(!allowedTags.has(node.tagName)){node.replaceWith(...node.childNodes);continue}const href=node.getAttribute('href'),src=node.getAttribute('src'),alt=node.getAttribute('alt');for(const attribute of [...node.attributes])node.removeAttribute(attribute.name);if(node.tagName==='A'){const safeHref=safeUrl(href,base,true);if(safeHref){node.href=safeHref;node.target='_blank';node.rel='noopener noreferrer'}}if(node.tagName==='IMG'){const safeSrc=safeUrl(src,base,false);if(safeSrc){node.src=safeSrc;node.alt=alt??'';node.loading='lazy';node.referrerPolicy='no-referrer'}else node.remove()}}const imageNode=documentValue.querySelector('img[src]'),image=imageNode?.src??null,text=(documentValue.body.textContent??'').replace(/\s+/g,' ').trim(),content=document.createDocumentFragment();content.append(...documentValue.body.childNodes);return{text,image,content}}
function safeUrl(value,base,allowMail){if(!value)return null;try{const candidate=new URL(value,base);return candidate.protocol==='http:'||candidate.protocol==='https:'||(allowMail&&candidate.protocol==='mailto:')?candidate.href:null}catch{return null}}
function disconnectReadObserver(){readObserver?.disconnect();lastReadObserver?.disconnect();readObserver=null;lastReadObserver=null;for(const timer of readTimers.values())clearTimeout(timer);readTimers.clear();autoQueue.clear();if(autoFlushTimer)clearTimeout(autoFlushTimer);autoFlushTimer=null}
function handleReadIntersections(entries){for(const entry of entries){const id=entry.target.dataset.articleId,article=articles.find(item=>item.id===id);if(!article||!isUnread(article)||article.isUnreadPinned)continue;if(entry.isIntersecting){if(!readTimers.has(id))readTimers.set(id,setTimeout(()=>{readTimers.delete(id);queueAutomaticRead(id)},1000))}else if(readTimers.has(id)){clearTimeout(readTimers.get(id));readTimers.delete(id)}}}
function setupReadObserver(){disconnectReadObserver();if(!autoRead.checked)return;const sentinels=[...cards.querySelectorAll('.read-sentinel')].filter(sentinel=>{const article=articles.find(item=>item.id===sentinel.dataset.articleId);return article&&isUnread(article)&&!article.isUnreadPinned});if(!sentinels.length)return;readObserver=new IntersectionObserver(handleReadIntersections,{rootMargin:'0px 0px -20% 0px',threshold:0});for(const sentinel of sentinels.slice(0,-1))readObserver.observe(sentinel);lastReadObserver=new IntersectionObserver(handleReadIntersections,{threshold:0});lastReadObserver.observe(sentinels.at(-1))}
function queueAutomaticRead(id){const article=articles.find(item=>item.id===id);if(!autoRead.checked||!article||!isUnread(article)||article.isUnreadPinned)return;autoQueue.add(id);if(!autoFlushTimer)autoFlushTimer=setTimeout(flushAutomaticReads,250)}
async function flushAutomaticReads(){autoFlushTimer=null;const ids=[...autoQueue].filter(id=>{const article=articles.find(item=>item.id===id);return article&&isUnread(article)&&!article.isUnreadPinned});autoQueue.clear();if(!ids.length)return;const response=await fetch('/api/articles/read',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({articleIds:ids,automatic:true})});if(!response.ok){status.textContent='Could not save automatic read progress.';return}for(const id of ids){const article=articles.find(item=>item.id===id);if(!article)continue;adjustFeedUnread(article,-1);article.isUnread=false;article.readAt=new Date().toISOString();sessionRead.add(id);const card=document.getElementById(`article-${id.replaceAll('-','')}`);if(card)updateCardReadAppearance(card,article)}updateViewActions();updateStatus()}
threshold.oninput=()=>{temporarilyVisible.clear();readLimit=25;render()};
showUnread.onclick=()=>{viewMode='unread';render()};showAll.onclick=()=>{viewMode='all';readLimit=25;render()};
layoutReading.onclick=()=>setLayout('reading');layoutScan.onclick=()=>setLayout('scan');layoutGallery.onclick=()=>setLayout('gallery');
toggleVoting.onclick=()=>setDisplayOptions(!showVoting,showLearning);toggleLearning.onclick=()=>setDisplayOptions(showVoting,!showLearning);
autoRead.onchange=()=>{localStorage.setItem('personalrss.autoRead',String(autoRead.checked));setupReadObserver()};
loadOlder.onclick=()=>{readLimit+=25;render()};
markUnread.onclick=async()=>{markUnread.disabled=true;status.textContent='Marking the whole feed unread…';const response=await fetch(`/api/feeds/${feed.id}/unread`,{method:'POST'});if(!response.ok){status.textContent='Could not mark this feed unread.';updateViewActions();return}for(const article of articles){article.isUnread=true;article.isUnreadPinned=false;article.readAt=null}sessionRead.clear();await refreshFeedState();render();notifyParent();const unread=feed.totalUnreadCount??feed.unreadCount??0;status.textContent=`Marked all ${unread} stored ${unread===1?'article':'articles'} unread across every score.`};
markRead.onclick=async()=>{const unread=feed.totalUnreadCount??feed.unreadCount??0;markRead.disabled=true;const response=await fetch(`/api/feeds/${feed.id}/viewed`,{method:'POST'});if(response.ok){for(const article of articles)if(isUnread(article)){article.isUnread=false;article.isUnreadPinned=false;article.readAt=new Date().toISOString();sessionRead.add(article.id);const card=document.getElementById(`article-${article.id.replaceAll('-','')}`);if(card)updateCardReadAppearance(card,article)}await refreshFeedState();updateViewActions();notifyParent();status.textContent=`Marked ${unread} ${unread===1?'article':'articles'} read across all scores. Loaded posts remain here until refresh.`}else{status.textContent='Could not mark this feed read.';updateMarkReadAction()}};
start().then(()=>{if(location.hash)document.querySelector(location.hash)?.scrollIntoView()}).catch(error=>{status.textContent='Could not load this preview.';console.error(error)});
</script></body></html>
""";
